// Generated by Manus game sharing.
import { spawnSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import { basename, join } from 'node:path'
import { assembleThreejsShareSite, GameSharingValidationError } from './metadata.mjs'

// Publication metadata is public project content; no runtime credentials are embedded here.
const publicationOrigin = process.env.PUBLICATION_ORIGIN || "https://zephyrwing-ai.github.io/paintwar"
const outputDirectory = "dist"
const projectTitle = "涂地大作战"
// Run the original script through the invoking package manager, preserving argument quoting.
const packageManager = process.env.npm_execpath
if (!packageManager) throw new Error('Run sharing through the package.json build script')
// A nested npm invocation can inherit the outer pnpm user agent.
const npm = ['npm', 'npm-cli.js', 'npm.js'].includes(basename(packageManager))
const result = spawnSync(process.execPath, [packageManager, 'run', "manus:build-source", ...(npm ? ['--'] : []), ...process.argv.slice(2)], { stdio: 'inherit' })
if (result.error) throw result.error
if (result.status !== 0) process.exit(result.status ?? 1)
try {
  const snapshot = assembleThreejsShareSite(process.cwd(), outputDirectory, { publicationOrigin, projectTitle })
  if (!snapshot?.assets.og || !snapshot.assets.favicon) throw new GameSharingValidationError('Sharing requires both OG and favicon images')
  for (const asset of Object.values(snapshot.assets)) {
    if (!existsSync(join(outputDirectory, asset.path))) throw new GameSharingValidationError(`Sharing asset was not written: ${asset.path}`)
  }
  const metadata = JSON.parse(readFileSync(join(outputDirectory, 'game-sharing.json'), 'utf8'))
  if (metadata.publicationOrigin !== snapshot.publicationOrigin) throw new GameSharingValidationError('Sharing publication URL does not match the build')
  console.log(`[sharing] OG and favicon included for ${publicationOrigin}`)
} catch (error) {
  const reason = error instanceof GameSharingValidationError ? error.message
    : error instanceof SyntaxError ? 'game-sharing.json must contain valid JSON'
    : error?.code === 'ENOENT' ? 'A configured PNG asset or build output is missing'
    : 'Check file access and the configured build output'
  console.error('[sharing] ' + reason)
  process.exit(1)
}
